"use client";

import { useState } from "react";
import { Plus, Trash2, Edit, BookOpen, Tag, X } from "lucide-react";
import { 
  createAiModel, 
  setDefaultModel, 
  toggleModel, 
  deleteModel,
  saveAppSetting,
  toggleFeatureStatus,
  toggleFeaturePro,
  createCategory,
  createProduct, updateProduct,
  deleteCategory,
  deleteProduct
} from "./admin-actions";

export function AdminSettingsContent({ activeTab, adminData }: { activeTab: string, adminData: any }) {
  const { models, settings, features, categories, products } = adminData;
  const [loading, setLoading] = useState(false);

  
  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setLoading(true);
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("/api/upload", { method: "POST", body: formData });
      const data = await res.json();
      if (data.url) {
        const input = document.getElementById("coverUrlInput") as HTMLInputElement;
        if (input) input.value = data.url;
        const editInput = document.getElementById("editCoverUrlInput") as HTMLInputElement;
        if (editInput) editInput.value = data.url;
        alert("Cover berhasil diupload!");
      }
    } catch (err) {
      alert("Gagal upload cover");
    } finally {
      setLoading(false);
    }
  };

  
  const [showAddProduct, setShowAddProduct] = useState(false);
  const [editingProduct, setEditingProduct] = useState<any>(null);
  const [showAddCategory, setShowAddCategory] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [coverUrl, setCoverUrl] = useState("");

  const ORDER = [
    "Master Blueprint",
    "Bio Builder",
    "Idea Rooms",
    "Script Builder",
    "Carousel Prompt Builder",
    "ATM Content Builder",
    "Ebook Prompt Builder",
    "Content Calendar"
  ];
  const sortedFeatures = [...features].sort((a, b) => ORDER.indexOf(a.name) - ORDER.indexOf(b.name));

  
  const [newModel, setNewModel] = useState({ name: "", modelId: "", provider: "google" });
  const [apiKey, setApiKey] = useState(settings.find((s:any) => s.key === "DEFAULT_GEMINI_API_KEY")?.value || "");

  const handleSaveApiKey = async () => {
    setLoading(true);
    await saveAppSetting("DEFAULT_GEMINI_API_KEY", apiKey);
    alert("API Key berhasil disimpan!");
    setLoading(false);
  };

  const handleAddModel = async () => {
    if (!newModel.name || !newModel.modelId) return;
    setLoading(true);
    await createAiModel(newModel);
    setNewModel({ name: "", modelId: "", provider: "google" });
    setLoading(false);
  };

  return (
    <>
      {/* Tab: API Key Global */}
      {activeTab === "api" && (
        <div className="border border-gray-200 dark:border-white/5 rounded-2xl p-6 bg-white dark:bg-[#121214]">
          <div className="mb-6">
            <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-1">Pengaturan API Key Global</h2>
            <p className="text-sm text-gray-500 dark:text-gray-400">Atur Default API Key yang akan digunakan oleh sistem jika pengguna tidak memasukkan API Key mereka sendiri.</p>
          </div>
          
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Default Gemini API Key</label>
              <input 
                type="password" 
                value={apiKey}
                onChange={e => setApiKey(e.target.value)}
                placeholder="AIzaSy..." 
                className="w-full bg-gray-50 dark:bg-[#1f1f23] border border-gray-200 dark:border-white/10 rounded-lg px-4 py-2.5 text-sm focus:ring-2 focus:ring-orange-500 focus:outline-none font-mono"
              />
            </div>
            <button 
                        onClick={async () => {
                          if (confirm('Yakin ingin menghapus E-book ini?')) {
                            setLoading(true);
                            await deleteProduct(prod.id);
                            setLoading(false);
                          }
                        }}
                        className="flex items-center gap-1.5 px-3 py-1.5 bg-transparent hover:bg-red-50 dark:hover:bg-red-900/10 border border-gray-200 dark:border-white/10 text-gray-600 dark:text-gray-400 hover:text-red-500 dark:hover:text-red-400 rounded-lg transition-colors text-xs font-bold"
                      >
                        <Trash2 size={14} /> Hapus
                      </button>
                    </div>
                    {prod.isProOnly ? (
                      <span className="text-sm font-black text-purple-600 dark:text-purple-400">Pro Only</span>
                    ) : (
                      <span className="text-sm font-black text-green-600 dark:text-green-500">Gratis</span>
                    )}
                  </div>
                </div>
              </div>
            ))}
            {products.length === 0 && (
              <div className="col-span-full py-12 flex flex-col items-center justify-center text-gray-400 border-2 border-dashed border-gray-200 dark:border-white/10 rounded-2xl">
                <BookOpen size={48} className="mb-3 opacity-20" />
                <p>Belum ada produk e-book yang ditambahkan.</p>
              </div>
            )}
            </div>
          </div>
        </div>
      )}
    </>
  );
}
